import numpy as np


def run(frames, params):
    p = params or {}
    mt, dt = float(p.get('marker_change_px', 1)), float(p.get('depth_change_mm', 0.05))
    if not (np.isfinite(mt) and 0 < mt <= 100 and np.isfinite(dt) and 0 < dt <= 10):
        return {'diagnosis': 'unknown_invalid_thresholds'}
    fs = list(frames)[-4:]
    def num(x):
        if x is None:
            return None
        x = float(x)
        return round(x, 4) if np.isfinite(x) and abs(x) < 1e9 else None
    def arr(s, k):
        x = s.get(k)
        return x.astype(float, copy=False) if isinstance(x, np.ndarray) else None
    def advanced(a, b):
        for key in ('simulation_time_s', 'physics_step'):
            x, y = a.get(key), b.get(key)
            if x is not None and y is not None and np.isfinite(x) and np.isfinite(y):
                return bool(y > x)
        return False
    def markers(s):
        meta = {'marker_units': 'pixels', 'marker_coordinate_order': 'x,y',
                'marker_origin': 'top_left', 'marker_axes': 'x_right_y_down'}
        if any(s.get(k) != v for k, v in meta.items()):
            return None
        r, d = arr(s, 'marker_reference'), arr(s, 'marker_displacement')
        size = s.get('image_size', ())
        if r is None or d is None or r.ndim != 2 or r.shape[1] != 2 or d.shape != r.shape:
            return None
        if len(size) != 2 or min(size) <= 0 or len(r) < 12:
            return None
        h, w = size
        ok = np.isfinite(r).all(1) & np.isfinite(d).all(1)
        ok &= (r[:, 0] >= 0) & (r[:, 0] < w) & (r[:, 1] >= 0) & (r[:, 1] < h)
        ok &= (np.abs(d) < 2*max(h, w)).all(1)
        if ok.mean() < 0.8:
            return None
        r, d = r[ok], d[ok]
        r, inv = np.unique(np.round(r, 3), axis=0, return_inverse=True)
        d = np.array([np.median(d[inv == j], axis=0) for j in range(len(r))])
        return (r, d) if len(r) >= 12 else None
    def shared(ss):
        # Every delta in a reversal uses the SAME spatially matched support.
        kind, size = ss[0].get('reference_kind'), tuple(ss[0].get('image_size', ()))
        if kind is None or any(s.get('reference_kind') != kind or tuple(s.get('image_size', ())) != size for s in ss):
            return None, None
        ms = [markers(s) for s in ss]
        if any(m is None for m in ms):
            return None, None
        anchor = ms[0][0]
        i = np.arange(len(anchor))
        keep, indices = np.ones(len(anchor), dtype=bool), [i]
        for r, d in ms[1:]:
            dist = np.sum((anchor[:, None] - r[None, :])**2, axis=2)
            j = dist.argmin(1)
            keep &= (dist[i, j] <= 1.0) & (dist.argmin(0)[j] == i)
            indices.append(j)
        coverage = float(keep.sum()/max(len(m[0]) for m in ms))
        if keep.sum() < 12 or coverage < 0.7:
            return None, coverage
        return [m[1][j[keep]] for m, j in zip(ms, indices)], coverage
    def depth(a, b):
        native = 'native_sensor_camera_depth_not_indentation'
        if any(s.get('depth_units') != 'mm' or s.get('depth_semantics') != native for s in (a, b)):
            return None
        x, y = arr(a, 'depth'), arr(b, 'depth')
        if x is None or y is None or x.ndim != 2 or x.shape != y.shape or not x.size:
            return None
        if tuple(a.get('depth_image_size', ())) != x.shape or tuple(b.get('depth_image_size', ())) != y.shape:
            return None
        valid = np.isfinite(x) & np.isfinite(y) & (x > 0) & (y > 0)
        if valid.sum() < 64 or valid.mean() < 0.8:
            return None
        return float(np.mean(np.abs(y[valid]-x[valid]) > dt))
    def hand(a, b):
        a, b = a.get('state', {}), b.get('state', {})
        if any(s.get('pose_frame') != 'world' or s.get('position_units') != 'm' for s in (a, b)):
            return None
        if a.get('eef_frame') is None or a.get('eef_frame') != b.get('eef_frame'):
            return None
        x, y = arr(a, 'eef_pose_wxyz'), arr(b, 'eef_pose_wxyz')
        if x is None or y is None or x.shape != (7,) or y.shape != (7,):
            return None
        if not np.isfinite(x).all() or not np.isfinite(y).all() or max(np.max(np.abs(x)), np.max(np.abs(y))) > 1e5:
            return None
        q, r = np.linalg.norm(x[3:]), np.linalg.norm(y[3:])
        if min(q, r) < 1e-8:
            return None
        angle = np.degrees(2*np.arccos(np.clip(abs(np.dot(x[3:]/q, y[3:]/r)), 0, 1)))
        return [float(1000*np.linalg.norm(y[:3]-x[:3])), float(angle)]
    def side(i, name):
        return fs[i].get('tactile', {}).get(name, {})
    def magnitude(d):
        return float(np.median(np.linalg.norm(d, axis=1)))
    out = {'frames': [[i, num(f.get('step'))] for i, f in enumerate(fs)],
           'diagnosis': 'unknown_need_two_advanced_frames', 'latest': None, 'reversal': None,
           'applicability': 'Same episode, continuous references; matched support only. Depth support means co-occurrence.',
           'uncertainty': 'Thresholds are descriptive; tracking accuracy and cause unknown. Pixels are not force; depth is not indentation. Quiet is not evidence of contact absence or physical stability.'}
    if len(fs) < 2:
        return out
    i, j = len(fs)-2, len(fs)-1
    if advanced(fs[i], fs[j]):
        mags, fractions, cover = [], [], []
        for name in ('left', 'right'):
            a, b = side(i, name), side(j, name)
            ds, c = shared([a, b])
            mags.append(None if ds is None else magnitude(ds[1]-ds[0]))
            fractions.append(depth(a, b))
            cover.append(c)
        h = hand(fs[i], fs[j])
        out['latest'] = {'frames': [i, j], 'marker_px_lr': list(map(num, mags)),
                         'depth_fraction_lr': list(map(num, fractions)), 'coverage_lr': list(map(num, cover)),
                         'hand_mm_deg': None if h is None else list(map(num, h))}
        out['diagnosis'] = 'unknown_incomplete_tactile_evidence'
        if all(v is not None for v in mags + fractions):
            m, d = [v >= mt for v in mags], [v > 0.01 for v in fractions]
            if any(x and y for x, y in zip(m, d)):
                out['diagnosis'] = 'marker_change_with_depth_support'
            elif any(m):
                out['diagnosis'] = 'marker_change_without_depth_support'
            elif any(d):
                out['diagnosis'] = 'depth_change_without_marker_support'
            else:
                context = 'hand_unknown' if h is None else ('fixed_hand' if h[0] <= 0.2 and h[1] <= 0.1 else 'moving_hand')
                out['diagnosis'] = 'small_bilateral_change_' + context
    best = -1.0
    for i in range(len(fs)-2):
        if not all(advanced(fs[k], fs[k+1]) for k in (i, i+1)):
            continue
        peaks, nets, depths, coverage = [], [], [], []
        for name in ('left', 'right'):
            ss = [side(k, name) for k in range(i, i+3)]
            ds, c = shared(ss)
            dd = [depth(ss[a], ss[b]) for a, b in ((0, 1), (1, 2), (0, 2))]
            if ds is None or any(v is None or v > 0.01 for v in dd):
                break
            x, y = ds[1]-ds[0], ds[2]-ds[1]
            vx, vy = np.median(x, axis=0), np.median(y, axis=0)
            nx, ny = np.linalg.norm(vx), np.linalg.norm(vy)
            mx, my, net = magnitude(x), magnitude(y), magnitude(x+y)
            if min(nx, ny) < mt or nx < 0.75*mx or ny < 0.75*my:
                break
            if np.dot(vx, vy) >= -0.8*nx*ny or net > 0.35*max(mx, my):
                break
            peaks.append(max(mx, my)); nets.append(net); depths.append(max(dd)); coverage.append(c)
        if len(peaks) == 2 and min(peaks) > best:
            best = min(peaks)
            out['reversal'] = {'frames': [i, i+1, i+2], 'peak_px_lr': list(map(num, peaks)),
                               'net_px_lr': list(map(num, nets)), 'max_depth_fraction_lr': list(map(num, depths)),
                               'coverage_lr': list(map(num, coverage)),
                               'evidence': 'bilateral_reversible_marker_excursion_without_depth_support',
                               'interpretation': 'Not sustained directional evidence; physical cause unknown.'}
    return out
